head.script:
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.setVal = function() {
    scwin.fireDbClick(WebSquare.wUnit.getDomById('gridView1_cell_0_0'));
}
scwin.checkVal = function() {
    return WebSquare.wUnit.getDomById($p.id+"gridView1_cell_0_0").innerText == '-999';
}
scwin.checkVal2 = function() {
    return WebSquare.wUnit.getObjById($p.id+"wq_uuid_4").getValue() == '-999';
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 그리드뷰의 첫번째 컬럼에 -999값을 입력한다.
    //1. After running the sample file, enter a value of -999 in the first column of the grid view.
    WebSquare.wUnit.addCommand("set", "scwin.setVal()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_gridView1__col1').setValue(-999)");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_0_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. -999값이 입력된다.(이전에는 -99까지만 입력됨)
    //1. The value of -999 is entered (Previously only up to -99)
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. inputbox를 클릭하고 -999값을 입력한다.
    //2. Click inputbox and enter a value of -999.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_4').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_4').setValue(-999)");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_4').blur()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. -999값이 입력된다.(이전에는 -99까지만 입력됨)
    //2. The value of -999 is entered (previously only -99 is entered)
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 28-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
